## ---- tbl-22-spreads ----
# What the US curve and the US spreads did across the credit crisis and the
# rates shock, in basis points from the week before each episode to its last
# week, with the cumulative return of the US ten-year government, investment-
# grade and high-yield bonds over the same months.
ep_curve <- dplyr::bind_rows(lapply(c("credit_crisis", "rates_shock"), function(k) {
  i <- which(in_episode(cv$date, k)); i0 <- min(i) - 1L; i1 <- max(i)
  m <- in_episode(dates, k)
  cum <- function(id) prod(1 + as.numeric(Am[m, id])) - 1
  tibble::tibble(episode = sim_episodes$label[sim_episodes$episode == k],
                 d_y2  = 1e4 * (Y_us[i1, "y2"] - Y_us[i0, "y2"]),
                 d_y10 = 1e4 * (Y_us[i1, "y10"] - Y_us[i0, "y10"]),
                 d_ig  = 1e4 * (cv$US_IG_Spread[i1] - cv$US_IG_Spread[i0]),
                 d_hy  = 1e4 * (cv$US_HY_Spread[i1] - cv$US_HY_Spread[i0]),
                 gov10 = cum(id_of("US", 10)), ig10 = cum(id_of("US", 10, "credit", "IG")),
                 hy10  = cum(id_of("US", 10, "credit", "HY")))
}))
ep_curve |>
  dplyr::mutate(dplyr::across(d_y2:d_hy, ~ sprintf("%+.0f", .x)),
                dplyr::across(gov10:hy10, ~ sprintf("%+.1f%%", 100 * .x))) |>
  kable(align = "lrrrrrrr",
        col.names = c("", "Δ 2y", "Δ 10y", "Δ IG spread", "Δ HY spread",
                      "gov 10y", "IG 10y", "HY 10y"))

## ---- spread-facts ----
cc <- ep_curve[ep_curve$episode == "credit crisis", ]; rsk <- ep_curve[ep_curve$episode == "rates shock", ]
stopifnot(cc$d_y10 < 0, cc$d_hy > 0, cc$gov10 > 0, cc$hy10 < 0, rsk$d_y10 > 0, rsk$gov10 < 0)
